@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Adeepl
@description Soothing pastel theme for DeepL
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document regexp("https:\\/\\/www.deepl.com\\/?(.*\\/)translator.*$") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    /* header */
    .BasePageHeader-module--container--d81cb {
      background-color: @mantle !important;
    }

    /* background */
    body {
      background-color: @base !important;
      color: @text !important;
    }

    .bg-neutral-next-50,
    .bg-white,
    .contextual-menu-dragging-area,
    input {
      background-color: @base !important;
    }

    .pageFooterV2-module--footerOuterContainer--0b055 {
      background-color: @mantle !important;
    }

    .scrollablePopiverListRoot-module--root--588fe {
      background-color: @base !important;
    }

    /* text color */
    h1,
    h2,
    h3,
    h4,
    p,
    a,
    button,
    span,
    input,
    ul,
    li,
    .mb-3,
    .mb-4,
    .GlossaryModalWithIllustration-module--content--2bf03,
    .lmt__glossary_editor_glossaryName {
      color: @text !important;
    }

    .text-neutral-next-600 {
      color: @subtext0 !important;
    }

    /* privacy notice */
    .cookieBanner-module--container--9baef {
      background-color: @surface0 !important;
      color: @text !important;
    }

    .button-module--button--4f58d.button-module--color_primaryAlt3--cd3cf {
      border-color: @text !important;
    }

    /* side menu */
    .classicSidemenu-module--menuContainer--35157 {
      background-color: @base !important;
    }

    /* borders */
    .border-black {
      border-color: @surface2 !important;
    }

    .border-neutral-next-100,
    .StartFreeTrialButton-module--startFreeTrialButton--bd671 {
      border-color: @surface0 !important;
    }

    .divide-y > :not([hidden]) ~ :not([hidden]) {
      border-color: @base;
    }

    .TranslatorTab-module--active--0b6ea
      .TranslatorTab-module--innerLower--8a080 {
      background-color: @accent !important;
    }

    .ring-neutral-next-900 {
      --tw-ring-color: @surface2;
    }

    .border-neutral-next-900 {
      border-color: @surface2 !important;
    }

    input {
      border-color: @surface0 !important;
    }

    /* hover */
    button:hover,
    .bg-blue-next-500:hover {
      background-color: @surface1 !important;
    }

    a:hover {
      background-color: @mantle !important;
    }

    .FlyoutMenuButton-module--flyoutMenuButton--97ae6:hover {
      background-color: @mantle !important;
    }

    [class*="SourceTranslatorArea-module--focusBorder--"]:has(
      div[contenteditable="true"]:focus
    ) {
      border-color: @accent;
    }

    [class*="PageHeaderLink-module--pageHeaderLink--"]:not(
      [class*="PageHeaderLink-module--nohover--"]
    ):hover {
      color: @accent;
      border-color: @accent;
    }

    .hover\:bg-\[\#B4DAE8\]:hover {
      background-color: @surface2 !important;
    }

    /* highlight */
    .bg-\[\#E1F0F5\] {
      background-color: @surface1 !important;
    }

    /* buttons */
    .TranslatorTab-module--cardButton--4b203,
    .bg-\[\#EDF8FC\] {
      background-color: @surface0 !important;
      border-color: @surface0 !important;
    }

    .StartFreeTrialButton-module--startFreeTrialButton--bd671,
    .bg-blue-next-50 {
      background-color: @surface0 !important;
    }

    .bg-blue-next-500 {
      background-color: @surface0;
      border-color: @surface0;
    }

    .LanguageSelector-module--wrapper--f9f17 {
      --button-background: @surface0 !important;
      --button-border-color: @surface0 !important;
      color: @base !important;
    }

    .CareerBanner-module--container--2ac20 {
      background-color: @surface0 !important;
    }

    /* glossary button */
    .lmt__glossaryButton,
    .lmt__glossaryButton__desktop:hover,
    .ModalDialogContent-module--content--5751e {
      background-color: @surface0 !important;
    }

    .lmt__glossary_acceptButton,
    .lmt__glossary_editor,
    .lmt__glossary_editor_subBar_top,
    .lmt__glossary_editor_subBar_bottom,
    .lmt__glossary_editor_mainBar,
    .Select-module--wrapper--53ec7 .Select-module--flyout--c91f3,
    .lmt_firstEntry-content,
    .lmt__glossary_newEntry_langButton,
    .Select-module--wrapper--53ec7,
    .Select-module--button--f032e {
      background-color: @surface0 !important;
      border-color: @surface0 !important;
    }

    .desktop-glossary-overwrites .lmt__language_select__menu {
      background-color: @surface0 !important;
      color: @text !important;
    }

    .lmt__glossary_newEntry_langDropdown.lmt__language_select__menu
      button
      .langName {
      color: @text !important;
    }

    /* pro banner */
    .ProBanner2021-module--wrapper--c7e3d,
    .p-8 {
      background: @base !important;
    }

    /* some button colors */
    .badge-module--badge--c9ebe.badge-module--proDark--a4d4e {
      background-color: @green;
      color: @base !important;
    }

    .button-module--button--a854e.button-module--color_secondary--f171e {
      background-color: @peach;
      border-color: @peach !important;
      color: @base !important;
    }

    .button-module--button--a854e.button-module--variant_outline--b937c {
      background-color: @surface0 !important;
      border-color: @surface0 !important;
    }

    .button-module--button--a854e.button-module--color_primary--bfa59 {
      background-color: @blue !important;
      border-color: @blue !important;
      color: @base !important;
    }

    /* dropdowns */
    .ProductUpdatesContainer-module--updateContainer--16394,
    .ProductUpdateFooter-module--updateFooter--b46f0,
    .LanguageSelector-module--flyout--6bfe6 {
      background-color: @base !important;
      border-color: @surface0 !important;
    }

    /* allow mic/get extension prompt */
    .bg-neutral-next-900,
    .bg-blue-next-800 {
      background-color: @surface0 !important;
      color: @text !important;
    }

    /* icons, svgs and images */
    svg {
      color: @text !important;
    }

    .lmt__glossary_ad_checkmark,
    .lmt__glossary_arrowDown {
      border-color: @text !important;
    }

    path,
    .DeeplLogoText-module--logoText--34a4f,
    .ProBanner2021-module--lockitem--febe3,
    .FlyoutMenuButton-module--flyoutMenuButton--97ae6::after,
    #top-navi-sidemenu-opener,
    .pageFooterV2-module--socialMediaLinks--71305,
    .ProBanner2021-module--checkitem--2d8e7,
    [src*="https://static.deepl.com/img/app_desktop.svg"] {
      filter: @text-filter;
    }

    .Logo-module--logoImg--1ee7e,
    .LogoLink-module--logoText--33735,
    .deeplLogo-module--logo--ffd7a {
      filter: @blue-filter;
    }
  }
}

/* ==UserStyle==
@name Claude Catppuccin
@namespace github.com/catppuccin/userstyles/styles/claude
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/claude
@version 2026.11.01
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/claude/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aclaude
@description Soothing pastel theme for Claude
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("claude.ai") {
  :root[data-color-version="v2"] {
    &[data-mode="dark"] {
      #catppuccin(@darkFlavor);
    }
    &[data-mode="light"] {
      #catppuccin(@lightFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --accent-brand: #hslify(@accent)[];
    --accent-000: #hslify(@accent)[];
    --accent-100: #hslify(@accent)[];
    --accent-200: #hslify(lighten(@accent, 5%))[];
    --accent-900: #hslify(darken(@accent, 10%))[];
    --accent-main-000: #hslify(@accent)[];
    --accent-main-100: #hslify(@accent)[];
    --accent-main-200: #hslify(@accent)[];
    --accent-main-900: #hslify(@accent)[];
    --accent-pro-000: #hslify(@accent)[];
    --accent-pro-100: #hslify(@accent)[];
    --accent-pro-200: #hslify(@accent)[];
    --accent-pro-900: #hslify(@accent)[];
    --accent-secondary-000: #hslify(@accent)[];
    --accent-secondary-100: #hslify(@accent)[];
    --accent-secondary-200: #hslify(@accent)[];
    --accent-secondary-900: #hslify(@accent)[];
    --bg-000: #hslify(@surface0)[];
    --bg-100: #hslify(@base)[];
    --bg-200: #hslify(@mantle)[];
    --bg-300: #hslify(@surface0)[];
    --bg-400: #hslify(@surface1)[];
    --bg-500: #hslify(@surface2)[];
    --brand-000: #hslify(@accent)[];
    --brand-100: #hslify(lighten(@accent, 5%))[];
    --brand-200: #hslify(lighten(@accent, 5%))[];
    --brand-900: #hslify(@crust)[];
    --border-000: #hslify(@base)[];
    --border-100: #hslify(@crust)[];
    --border-200: #hslify(@crust)[];
    --border-300: #hslify(@overlay0)[];
    --border-400: #hslify(@overlay1)[];
    --border-500: #hslify(@overlay2)[];
    --danger-000: #hslify(@maroon)[];
    --danger-100: #hslify(@red)[];
    --danger-200: #hslify(@red)[];
    --danger-900: #hslify(@pink)[];
    --oncolor-000: #hslify(darken(@mantle, 5%))[];
    --oncolor-100: #hslify(@mantle)[];
    --oncolor-200: #hslify(@mantle)[];
    --oncolor-300: #hslify(lighten(@mantle, 5%))[];
    --success-000: #hslify(@green)[];
    --success-100: #hslify(lighten(@green, 5%))[];
    --success-200: #hslify(lighten(@green, 5%))[];
    --success-900: #hslify(lighten(@green, 15%))[];
    --text-000: #hslify(darken(@text, 5%))[];
    --text-100: #hslify(@text)[];
    --text-200: #hslify(@text)[];
    --text-300: #hslify(@subtext0)[];
    --text-400: #hslify(@subtext1)[];
    --text-500: #hslify(@subtext0)[];
    --warning-000: #hslify(@yellow)[];
    --warning-100: #hslify(lighten(@yellow, 5%))[];
    --warning-200: #hslify(lighten(@yellow, 5%))[];
    --warning-900: #hslify(lighten(@yellow, 15%))[];

    /* Claude Design System (dropdowns, tooltips, dialogs, popovers, banners).
       The root element is itself a .cds-root, and its --cds-page-bg paints the
       page, so match it as well as nested roots. */
    &.cds-root,
    .cds-root {
      --cds-surface-0: @crust !important;
      --cds-surface-1: @mantle !important;
      --cds-surface-2: @base !important;
      --cds-surface-3: @surface0 !important;
      --cds-surface-panel: @base !important;
      --cds-surface-popover: @surface0 !important;

      --cds-text-primary: @text !important;
      --cds-text-secondary: @subtext1 !important;
      --cds-text-muted: @subtext0 !important;
      /* .text-muted-as-secondary resolves through this before --cds-text-secondary. */
      --cds-fizzy-lake-color-secondary: @subtext1 !important;
      --cds-text-disabled: fade(@text, 35%) !important;
      --cds-text-accent: @accent !important;
      --cds-text-danger: @red !important;
      --cds-text-success: @green !important;
      --cds-text-warning: @yellow !important;
      --cds-text-pro: @accent !important;
      --cds-text-git-added: @green !important;
      --cds-text-git-removed: @red !important;
      --cds-text-git-modified: @yellow !important;
      --cds-text-git-merged: @mauve !important;
      --cds-text-git-closed: @red !important;
      --cds-text-git-conflicting: @peach !important;
      --cds-text-git-draft: @overlay1 !important;

      --cds-fill-git-added: @green !important;
      --cds-fill-git-added-hover: lighten(@green, 10%) !important;
      --cds-fill-git-removed: @red !important;
      --cds-fill-git-removed-hover: lighten(@red, 10%) !important;
      --cds-fill-git-modified: @yellow !important;
      --cds-fill-git-modified-hover: lighten(@yellow, 10%) !important;
      --cds-fill-git-merged: @mauve !important;
      --cds-fill-git-merged-hover: lighten(@mauve, 10%) !important;
      --cds-fill-git-closed: @red !important;
      --cds-fill-git-closed-hover: lighten(@red, 10%) !important;
      --cds-fill-git-conflicting: @peach !important;
      --cds-fill-git-conflicting-hover: lighten(@peach, 10%) !important;
      --cds-fill-git-draft: @overlay1 !important;
      --cds-fill-git-draft-hover: lighten(@overlay1, 10%) !important;

      /* Brand orange (also recolored on the logo selector below). */
      --cds-clay: @accent !important;
      --cds-clay-emphasized: darken(@accent, 8%) !important;

      --cds-bg-accent: fade(@accent, 15%) !important;
      --cds-bg-danger: fade(@red, 15%) !important;
      --cds-bg-success: fade(@green, 15%) !important;
      --cds-bg-warning: fade(@yellow, 15%) !important;
      --cds-bg-pro: fade(@accent, 15%) !important;
      --cds-bg-neutral: fade(@text, 5%) !important;
      --cds-bg-neutral-hover: fade(@text, 10%) !important;
      --cds-bg-neutral-chip: fade(@text, 5%) !important;
      --cds-bg-neutral-chip-hover: fade(@text, 10%) !important;

      --cds-border: fade(@text, 10%) !important;
      --cds-border-strong: fade(@text, 20%) !important;
      --cds-border-stronger: fade(@text, 40%) !important;
      --cds-border-accent: fade(@accent, 30%) !important;
      --cds-border-danger: fade(@red, 30%) !important;
      --cds-border-success: fade(@green, 30%) !important;
      --cds-border-warning: fade(@yellow, 30%) !important;
      --cds-border-pro: fade(@accent, 30%) !important;

      --cds-fill-accent: @accent !important;
      --cds-fill-accent-hover: lighten(@accent, 5%) !important;
      --cds-fill-danger: @red !important;
      --cds-fill-danger-hover: lighten(@red, 5%) !important;
      --cds-fill-success: @green !important;
      --cds-fill-success-hover: lighten(@green, 5%) !important;
      --cds-fill-warning: @yellow !important;
      --cds-fill-warning-hover: lighten(@yellow, 5%) !important;
      --cds-fill-pro: @accent !important;
      --cds-fill-pro-hover: lighten(@accent, 5%) !important;
      --cds-fill-primary: @text !important;
      --cds-fill-primary-hover: @subtext1 !important;
      --cds-fill-secondary: fade(@text, 10%) !important;
      --cds-fill-secondary-hover: fade(@text, 15%) !important;
      --cds-fill-ghost-hover: fade(@text, 5%) !important;
      --cds-fill-disabled: fade(@text, 5%) !important;
      --cds-fill-control: fade(@text, 10%) !important;
      --cds-fill-control-hover: fade(@text, 20%) !important;
      --cds-fill-field: fade(@text, 10%) !important;

      --cds-on-primary: @base !important;
      --cds-on-accent: @base !important;
      --cds-on-danger: @base !important;
      --cds-on-success: @base !important;
      --cds-on-warning: @base !important;
      --cds-on-pro: @base !important;
      --cds-on-brand: @base !important;

      --cds-tooltip-bg: @surface0 !important;
      --cds-tooltip-fg: @text !important;

      --cds-focus-shadow:
        inset 0 0 0 1px @base, 0 0 0 1px @accent, 0 0 6px 1px fade(@accent, 60%)
        !important;

      --cds-segmented-control-track: fade(@text, 5%) !important;
      --cds-segmented-control-thumb: @surface0 !important;

      --cds-backdrop: fade(@crust, 50%) !important;

      /* Gray primitive ramp (light -> dark). Feeds --cds-neutral-* (mirrored
         in dark mode), the --cds-alpha-* overlay ramp, and the bg-gray and
         text-gray utilities, so it must stay light-to-dark in absolute terms
         whichever flavor is active. */
      & when (@flavor = latte) {
        --cds-gray-0: @base !important;
        --cds-gray-10: @base !important;
        --cds-gray-20: @base !important;
        --cds-gray-30: @mantle !important;
        --cds-gray-40: @mantle !important;
        --cds-gray-50: @crust !important;
        --cds-gray-60: @crust !important;
        --cds-gray-70: @crust !important;
        --cds-gray-80: @surface0 !important;
        --cds-gray-90: @surface0 !important;
        --cds-gray-100: @surface0 !important;
        --cds-gray-150: @surface1 !important;
        --cds-gray-200: @surface1 !important;
        --cds-gray-250: @surface2 !important;
        --cds-gray-300: @surface2 !important;
        --cds-gray-350: @overlay0 !important;
        --cds-gray-400: @overlay0 !important;
        --cds-gray-450: @overlay1 !important;
        --cds-gray-500: @overlay1 !important;
        --cds-gray-550: @overlay2 !important;
        --cds-gray-600: @overlay2 !important;
        --cds-gray-650: @subtext0 !important;
        --cds-gray-700: @subtext0 !important;
        --cds-gray-750: @subtext1 !important;
        --cds-gray-800: @subtext1 !important;
        --cds-gray-810: @text !important;
        --cds-gray-820: @text !important;
        --cds-gray-830: @text !important;
        --cds-gray-840: @text !important;
        --cds-gray-850: @text !important;
        --cds-gray-860: @text !important;
        --cds-gray-870: @text !important;
        --cds-gray-880: @text !important;
        --cds-gray-890: @text !important;
        --cds-gray-900: @text !important;
      }
      & when not(@flavor = latte) {
        --cds-gray-0: @text !important;
        --cds-gray-10: @text !important;
        --cds-gray-20: @text !important;
        --cds-gray-30: @text !important;
        --cds-gray-40: @text !important;
        --cds-gray-50: @subtext1 !important;
        --cds-gray-60: @subtext1 !important;
        --cds-gray-70: @subtext1 !important;
        --cds-gray-80: @subtext0 !important;
        --cds-gray-90: @subtext0 !important;
        --cds-gray-100: @subtext0 !important;
        --cds-gray-150: @overlay2 !important;
        --cds-gray-200: @overlay2 !important;
        --cds-gray-250: @overlay1 !important;
        --cds-gray-300: @overlay1 !important;
        --cds-gray-350: @overlay0 !important;
        --cds-gray-400: @overlay0 !important;
        --cds-gray-450: @surface2 !important;
        --cds-gray-500: @surface2 !important;
        --cds-gray-550: @surface1 !important;
        --cds-gray-600: @surface1 !important;
        --cds-gray-650: @surface0 !important;
        --cds-gray-700: @surface0 !important;
        --cds-gray-750: @surface0 !important;
        --cds-gray-800: @base !important;
        --cds-gray-810: @base !important;
        --cds-gray-820: @base !important;
        --cds-gray-830: @base !important;
        --cds-gray-840: @mantle !important;
        --cds-gray-850: @mantle !important;
        --cds-gray-860: @mantle !important;
        --cds-gray-870: @crust !important;
        --cds-gray-880: @crust !important;
        --cds-gray-890: @crust !important;
        --cds-gray-900: @crust !important;
      }
    }

    /* Epitaxy (Claude Code: file viewer, diff viewer, buttons, HUD) */
    .epitaxy-root {
      /* Surface ramp (z0 darkest/main -> z6 lightest) drives nearly everything else:
         panels, popovers, HUD, sliders, switches, tooltips, button depth colors. */
      --z0: @crust !important;
      --z1: @mantle !important;
      --z2: @base !important;
      --z3: @surface0 !important;
      --z4: @surface1 !important;
      --z5: @surface2 !important;
      --z6: @overlay0 !important;

      /* Foreground opacity ladder over the surface ramp. */
      --t0: fade(@text, 0%) !important;
      --t1: fade(@text, 4%) !important;
      --t2: fade(@text, 8%) !important;
      --t3: fade(@text, 12%) !important;
      --t4: fade(@text, 16%) !important;
      --t5: fade(@text, 25%) !important;
      --t6: fade(@text, 48%) !important;
      --t7: fade(@text, 70%) !important;
      --t8: fade(@text, 80%) !important;
      --t9: @text !important;

      --accent: @accent !important;
      --accent-hover: lighten(@accent, 5%) !important;
      --accent-20-brightness: mix(@accent, @crust, 20%) !important;

      /* Consumed both as a plain color (inline `fill: var(--accent-brand)` on
         the sparkle logo glyph) and via hsl(from ...)/relative-color syntax
         (.ra-action-brand), so it needs a real color, not a bare H S% L%
         triple. Shadows the :root-level --accent-brand above for anything
         under .epitaxy-root. */
      --accent-brand: @accent !important;

      /* Destructive-action red, feeds --fill-destructive-default/-hover. */
      --core-red: @red !important;
      --core-red-hover: lighten(@red, 5%) !important;

      --extended-green: @green !important;
      --extended-pink: @pink !important;
      --extended-purple: @mauve !important;
      --extended-yellow: @yellow !important;
      --extended-orange: @peach !important;

      /* Dark-mode-only literals that bypass the z-scale entirely upstream. */
      --surface-primary-elevated: fade(@crust, 95%) !important;
      --surface-prompt-blur: @mantle !important;
      --surface-prompt-focus-hover: @base !important;
    }

    /* dframe (sidebar + page frame; appears standalone, not only under
       .epitaxy-root) */
    .dframe-root {
      --df-bg-page-hsl: #hslify(@mantle)[] !important;
      --df-sidebar-bg: @mantle !important;
      --df-web-sidebar-bg: @mantle !important;
      --df-web-sidebar-bg-image: none !important;
      --df-hover: fade(@text, 5%) !important;
      --df-selected: fade(@text, 8%) !important;
      --panel-hairline: fade(@overlay0, 40%) !important;

      /* .dframe-sidebar/.dframe-card re-declare these directly (some as
         hardcoded literals), shadowing the values above -- override at the
         same level. */
      .dframe-sidebar,
      .dframe-card {
        --df-sidebar-bg: @mantle !important;
        --df-surface-primary: @mantle !important;
        --df-web-sidebar-bg: @mantle !important;
        --df-hover: fade(@text, 5%) !important;
        --df-selected: fade(@text, 8%) !important;
      }

      /* Home/Code segmented control track (hardcoded white literal in dark
         mode). */
      .df-pills[data-segmented] {
        background-color: fade(@text, 6%) !important;
      }
    }

    /* Side bar */
    nav.\!bg-bg-200 {
      background: @mantle !important;
    }

    /* Code blocks */
    .code-block__code {
      background: @crust !important;

      code {
        /* Default color */
        span {
          color: @text !important;
        }

        /* Green */
        span.token[style="color: rgb(152, 195, 121);"] {
          color: @green !important;
        }

        /* Yellow */
        span.token[style="color: rgb(209, 154, 102);"] {
          color: @yellow !important;
        }

        /* Blue */
        span.token[style="color: rgb(97, 175, 239);"] {
          color: @blue !important;
        }

        /* Red */
        span.token[style="color: rgb(224, 108, 117);"] {
          color: @red !important;
        }

        /* Magenta */
        span.token[style="color: rgb(198, 120, 221);"] {
          color: @mauve !important;
        }

        /* Gray */
        span.token[style="color: rgb(171, 178, 191);"] {
          color: @overlay2 !important;
        }
      }
    }
    /* Warning */
    div.bg-warning-900 {
      div,
      button {
        color: @base !important;
      }
    }
    /* Inline code */
    code.text-danger-000 {
      color: @accent !important;
    }

    /* Tooltip */
    div.bg-black\/80 {
      background: @crust !important;
    }
    div.text-white {
      color: @text !important;
    }
    div.bg-always-black\/80 {
      background: fade(@crust, 80%) !important;
    }
    div.bg-always-black\/80.text-always-white {
      color: @text !important;
    }

    /* Logo */
    div.text-\[\#D97757\] {
      color: @accent !important;
    }

    /* "New chat" plus icon */
    div.text-always-white svg {
      color: @base !important;
    }

    /* "Subscribe to Pro" and "Create Team Account" buttons */
    button.bg-accent-pro-100 > span.inline-block {
      color: @base !important;
    }

    /* Pay monthly/annually buttons */
    button.bg-accent-secondary-900 {
      span.text-text-000 {
        color: @base !important;
      }
      span.text-text-300 {
        color: @surface2 !important;
      }
      div.bg-accent-secondary-000 {
        background: darken(@accent, 15%) !important;
      }
    }

    /* Delete conversation button */
    div.\!text-danger-000.\[\&\[data-highlighted\]\]\:bg-danger-900[data-highlighted] {
      background: fade(@red, 20%) !important;
    }

    /* Checkbox */
    input[type="checkbox"] + div.bg-bg-000 {
      background: @text !important;
    }

    /* "Add writing example" button */
    button.\!text-accent-secondary-100.bg-accent-secondary-900 {
      color: @base !important;
      &:hover {
        color: @text !important;
      }
    }

    /* "Describe your style" list */
    button.\!bg-accent-secondary-900.text-accent-secondary-000 {
      color: @base !important;
    }

    /* "Be as descriptive as possible..." helper text */
    div.bg-accent-secondary-900.text-text-200 {
      color: @base !important;
    }

    /* "Preview with an example..." pills */
    button.hover\:bg-accent-secondary-900.hover\:text-accent-secondary-000 {
      color: @accent !important;
      &:hover {
        color: @base !important;
      }
    }

    /* "Previewing with ..." dropdown button */
    button.\!text-accent-secondary-100.hover\:\!bg-accent-secondary-900 {
      color: @accent !important;
      &:hover {
        color: @base !important;
      }
    }

    /* White background (e.g., toggle switch thumb) */
    .bg-white {
      background-color: @text;
    }
  }
}

#hslify(@color) {
  @raw: e(%("%s %s% %s%", hue(@color), saturation(@color), lightness(@color)));
}

