/* ==UserStyle==
@name NameMC Catppuccin
@namespace github.com/catppuccin/userstyles/styles/namemc
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/namemc
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/namemc/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Anamemc
@description Soothing pastel theme for NameMC
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("namemc.com") {
  :root[data-bs-theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  :root[data-bs-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    #bsButton(@col, @bgCol) {
      --bs-btn-color: @col;
      --bs-btn-hover-color: darken(@col, 5%);
      --bs-btn-active-color: darken(@col, 5%);
      --bs-btn-disabled-color: @col;

      --bs-btn-bg: @bgCol;
      --bs-btn-hover-bg: darken(@bgCol, 5%);
      --bs-btn-active-bg: darken(@bgCol, 5%);
      --bs-btn-disabled-bg: @bgCol;
      --bs-btn-border-color: @bgCol;
      --bs-btn-hover-border-color: @bgCol;
      --bs-btn-active-border-color: @bgCol;
      --bs-btn-disabled-border-color: @bgCol;
    }
    #bsButtonOutline(@col, @hover) {
      --bs-btn-color: @col;
      --bs-btn-hover-bg: @col;
      --bs-btn-active-bg: @col;
      --bs-btn-border-color: @col;
      --bs-btn-disabled-color: @col;
      --bs-btn-focus-shadow-rgb: @col;
      --bs-btn-hover-border-color: @col;
      --bs-btn-active-border-color: @col;
      --bs-btn-disabled-border-color: @col;

      --bs-btn-hover-color: @hover;
      --bs-btn-active-color: @hover;
    }

    --bs-body-color: @text;
    --bs-body-color-rgb: #lib.rgbify(@text)[];
    --bs-body-bg: @base;
    --bs-body-bg-rgb: #lib.rgbify(@base)[];
    --bs-emphasis-color: @text;
    --bs-emphasis-color-rgb: #lib.rgbify(@text)[];
    --bs-blue: @blue;
    --bs-indigo: @mauve;
    --bs-purple: @mauve;
    --bs-pink: @pink;
    --bs-red: @red;
    --bs-orange: @peach;
    --bs-yellow: @yellow;
    --bs-green: @green;
    --bs-teal: @teal;
    --bs-cyan: @sapphire;
    --bs-secondary-color: @subtext0;
    --bs-secondary-color-rgb: #lib.rgbify(@subtext0)[];
    --bs-tertiary-color: @subtext1;
    --bs-tertiary-color-rgb: #lib.rgbify(@subtext1)[];
    --bs-tertiary-bg: @base;
    --bs-tertiary-bg-rgb: #lib.rgbify(@base)[];
    --bs-secondary-text-emphasis: @subtext0;
    --bs-success-text-emphasis: @green;
    --bs-primary: @accent;
    --bs-primary-rgb: #lib.rgbify(@accent)[];
    --bs-secondary: @subtext0;
    --bs-secondary-rgb: #lib.rgbify(@subtext0)[];
    --bs-success: @green;
    --bs-success-rgb: #lib.rgbify(@green)[];
    --bs-info: @sky;
    --bs-info-rgb: #lib.rgbify(@sky)[];
    --bs-warning: @yellow;
    --bs-warning-rgb: #lib.rgbify(@yellow)[];
    --bs-danger: @red;
    --bs-danger-rgb: #lib.rgbify(@red)[];
    --bs-light: @base;
    --bs-light-rgb: #lib.rgbify(@base)[];
    --bs-dark: @text;
    --bs-dark-rgb: #lib.rgbify(@text)[];
    --bs-dark-text-emphasis: @text;
    --bs-primary-bg-subtle: @crust;
    --bs-secondary-bg-subtle: @mantle;
    --bs-success-bg-subtle: fade(@green, 20%);
    --bs-warning-bg-subtle: fade(@yellow, 20%);
    --bs-danger-bg-subtle: @base;
    --bs-secondary-border-subtle: @surface1;
    --bs-success-border-subtle: @green;
    --bs-info-border-subtle: @sky;
    --bs-warning-border-subtle: @yellow;
    --bs-danger-border-subtle: @red;
    --bs-link-color: @accent;
    --bs-link-color-rgb: #lib.rgbify(@accent)[];
    --bs-code-color: @accent;
    --bs-highlight-bg: @base;
    --bs-form-valid-color: @green;
    --bs-focus-ring-color: @accent;
    --bs-form-valid-border-color: @green;
    --bs-form-invalid-color: @red;
    --bs-form-invalid-border-color: @red;

    .btn-primary {
      #bsButton(@crust, @accent);
    }
    .btn-secondary {
      #bsButton(@text, @overlay0);
    }
    .btn-success {
      #bsButton(@crust, @green);
    }
    .btn-info {
      #bsButton(@crust, @sapphire);
    }
    .btn-warning {
      #bsButton(@crust, @yellow);
    }
    .btn-danger {
      #bsButton(@crust, @red);
    }
    .btn-light {
      #bsButton(@crust, @overlay2);
    }
    .btn-dark {
      #bsButton(@text, @surface0);
    }

    .btn-outline-primary {
      #bsButtonOutline(@accent, @text);
    }
    .btn-outline-secondary {
      #bsButtonOutline(@overlay0, @text);
    }
    .btn-outline-success {
      #bsButtonOutline(@green, @text);
    }
    .btn-outline-info {
      #bsButtonOutline(@sapphire, @crust);
    }
    .btn-outline-warning {
      #bsButtonOutline(@yellow, @crust);
    }
    .btn-outline-danger {
      #bsButtonOutline(@red, @text);
    }
    .btn-outline-light {
      #bsButtonOutline(@text, @crust);
    }
    .btn-outline-dark {
      #bsButtonOutline(@surface0, @text);
    }

    .text-success {
      color: @green !important;
    }

    .btn-link {
      --bs-btn-disabled-color: @overlay0;
      --bs-btn-disabled-border-color: transparent;
      --bs-btn-focus-shadow-rgb: #lib.rgbify(@blue)[];
    }

    /* i hate that this is necessary */
    .dropdown-menu {
      --bs-dropdown-header-color: @overlay1 !important;
      --bs-dropdown-border-color: @surface2 !important;
    }

    #header {
      form {
        div.input-group.input-group-lg {
          input.form-control {
            background-color: @surface0 !important;

            &:focus {
              border-color: @accent;
              box-shadow: none;
            }
          }
        }
      }
    }

    .navbar-nav .nav-item a {
      color: @text !important;

      &:hover {
        color: @subtext0 !important;
      }
      span {
        color: @text !important;

        &:hover {
          color: @subtext0 !important;
        }
      }
    }

    .card {
      background-color: @surface0 !important;
      color: @subtext0 !important;
      --bs-card-bg: @base !important;

      .card-header {
        border-color: @surface2 !important;
      }
    }

    /* skin display link */
    div.card-header {
      span {
        color: @text;

        &:hover {
          color: @accent !important;
        }
      }

      strong a {
        color: @accent !important;
      }
    }

    /* skin display background */
    .checkered {
      @dark: fade(@surface0, 40%);
      @light: fade(@surface1, 40%);
      @svg: escape(
        '<svg width="64" height="64" xmlns="http://www.w3.org/2000/svg"><path fill="@{dark}" d="M0 0h32v32H0z"/><path fill="@{light}" d="M32 0h32v32H32zM0 32h32v32H0z"/><path fill="@{dark}" d="M32 32h32v32H32z"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}");
    }

    /* skins page nav buttons */
    .nav.nav-pills {
      .nav-item .nav-link a {
        color: @text !important;
      }
      .nav-link.active {
        background-color: @accent !important;
        color: @crust !important;
      }
    }

    .page-item .page-link {
      background-color: @surface0 !important;
      border-color: @surface2 !important;
      color: @text;

      &.active {
        background-color: @accent !important;
      }

      &:focus,
      &:hover {
        box-shadow: none !important;
        color: @accent !important;
      }
    }

    .page-item.active .page-link {
      background-color: @accent !important;
      border-color: @accent !important;
      color: @crust !important;
    }

    /* single skin page */
    a.badge,
    span.badge {
      background-color: @accent !important;
      color: @crust !important;
    }

    /* usernames page */
    form#upcoming-form {
      div.row {
        label.col-form-label {
          color: @text !important;
        }

        div.col {
          .input-group {
            .input-group-text {
              background-color: @base !important;
              border-color: @surface2 !important;
            }
          }
        }
      }
    }

    .form-control,
    .form-select {
      background-color: @base !important;
      border-color: @surface2 !important;
      box-shadow: none !important;
      color: @subtext1 !important;

      &:focus {
        border-color: @accent !important;
        box-shadow: 0 0 0 0.25rem fade(@accent, 25%);
      }
    }

    /* server list page */
    .mc-red {
      color: @maroon !important;
    }
    .mc-dark-red {
      color: @red !important;
    }
    .mc-gold {
      color: @peach !important;
    }
    .mc-yellow {
      color: @yellow !important;
    }
    .mc-green,
    .mc-dark-green {
      color: @green !important;
    }
    .mc-aqua {
      color: @sky !important;
    }
    .mc-dark-aqua {
      color: @teal !important;
    }
    .mc-blue {
      color: @sapphire !important;
    }
    .mc-dark-blue {
      color: @blue !important;
    }
    .mc-light-purple {
      color: @pink !important;
    }
    .mc-dark-purple {
      color: @mauve !important;
    }

    /* profile page */
    .namemc-rank-10 {
      color: @green !important;
    }

    .namemc-rank-100,
    .namemc-rank-200,
    .namemc-rank-900,
    .namemc-rank-1000 {
      color: @red !important;
    }

    #uuid-select {
      background-color: @surface1 !important;
    }

    .card.mb-3 .card-header a {
      color: @accent !important;
    }

    .skin-button-selected {
      /* society if box-shadow-color existed */
      box-shadow: 0 0 6px @overlay0 !important;
      background-color: @overlay0 !important;
    }

    .player-list {
      a:hover {
        color: @subtext1 !important;
      }
    }

    .head-command,
    #head-command-select {
      background-color: @base !important;

      &:focus {
        border-color: @accent !important;
        box-shadow: none !important;
      }
    }

    button.head-command {
      border-color: @surface0 !important;
      color: @subtext1;

      &:hover {
        background-color: @surface1 !important;
        border-color: @surface2 !important;
        color: @text !important;
      }
    }

    #country {
      background-color: @mantle !important;
    }

    fieldset.form-group input.form-control {
      background-color: @mantle;
    }

    form > .row > .col > .input-group {
      #discord-input,
      #facebook-input,
      #github-input,
      #instagram-input,
      #reddit-input,
      #snapchat-input,
      #soundcloud-input,
      #spotify-input,
      #steam-input,
      #telegram-input,
      #tiktok-input,
      #threads-input,
      #twitch-input,
      #twitter-input,
      #youtube-input,
      fieldset.form-group input.form-control {
        background-color: @mantle;
      }
    }

    & when (@flavor = latte) {
      --bs-black: @text;
      --bs-black-rgb: #lib.rgbify(@text)[];
      --bs-white: @crust;
      --bs-white-rgb: #lib.rgbify(@crust)[];
      --bs-gray: @subtext0;
      --bs-gray-dark: @text;
      --bs-gray-100: @base;
      --bs-gray-200: @mantle;
      --bs-gray-300: @crust;
      --bs-gray-400: @surface0;
      --bs-gray-500: @surface2;
      --bs-gray-600: @overlay2;
      --bs-gray-700: @subtext0;
      --bs-gray-800: @subtext1;
      --bs-gray-900: @text;
      --bs-secondary-bg: @mantle;
      --bs-secondary-bg-rgb: #lib.rgbify(@mantle)[];
      --bs-primary-text-emphasis: @text;
      --bs-info-text-emphasis: @text;
      --bs-warning-text-emphasis: @text;
      --bs-danger-text-emphasis: @red;
      --bs-light-text-emphasis: @subtext0;
      --bs-info-bg-subtle: @surface0;
      --bs-light-bg-subtle: @base;
      --bs-dark-bg-subtle: @surface0;
      --bs-primary-border-subtle: @surface2;
      --bs-light-border-subtle: @mantle;
      --bs-dark-border-subtle: @surface2;
      --bs-link-hover-color: @accent;
      --bs-link-hover-color-rgb: #lib.rgbify(@accent)[];
      --bs-border-color: @crust;

      .mc-black {
        color: @text !important;
      }
      .mc-dark-gray {
        color: @subtext0 !important;
      }
      .mc-gray,
      .mc-reset {
        color: @overlay1 !important;
      }
      .mc-white {
        color: @base !important;
      }
    }

    & when not(@flavor = latte) {
      --bs-black: @crust;
      --bs-white: @text;
      --bs-gray: @overlay2;
      --bs-gray-dark: @surface2;
      --bs-secondary-bg: @surface0;
      --bs-secondary-bg-rgb: #lib.rgbify(@surface0)[];
      --bs-primary-text-emphasis: @sapphire;
      --bs-info-text-emphasis: @sky;
      --bs-warning-text-emphasis: @yellow;
      --bs-danger-text-emphasis: @maroon;
      --bs-light-text-emphasis: @text;
      --bs-info-bg-subtle: @crust;
      --bs-light-bg-subtle: @surface0;
      --bs-dark-bg-subtle: @mantle;
      --bs-primary-border-subtle: @mantle;
      --bs-light-border-subtle: @surface1;
      --bs-dark-border-subtle: @surface0;
      --bs-link-hover-color: @text;
      --bs-link-hover-color-rgb: #lib.rgbify(@text)[];
      --bs-border-color: @surface1;

      .mc-black {
        color: @crust !important;
      }
      .mc-dark-gray {
        color: @overlay0 !important;
      }
      .mc-gray,
      .mc-reset {
        color: @subtext0 !important;
      }
      .mc-white {
        color: @text !important;
      }
    }
  }
}

/* ==UserStyle==
@name GitHub Catppuccin
@namespace github.com/catppuccin/userstyles/styles/github
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/github
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/github/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Agithub
@description Soothing pastel theme for GitHub
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document /* Match every page on GitHub except github.com/home, github.com/features/*, and github.com/organizations/plan. */
regexp(
    "https:\/\/github\.com(?!(\/home$|\/features($|\/.*)|\/organizations\/plan)).*$"
  ),
  domain("gist.github.com"),
  domain("docs.github.com"),
  domain("viewscreen.githubusercontent.com") {
  [data-color-mode][data-color-mode="auto"] {
    @media (prefers-color-scheme: light) {
      &[data-light-theme="light"] {
        #catppuccin(@lightFlavor);
      }
      &[data-light-theme="dark"] {
        #catppuccin(@darkFlavor);
      }
    }

    @media (prefers-color-scheme: dark) {
      &[data-dark-theme="light"] {
        #catppuccin(@lightFlavor);
      }
      &[data-dark-theme="dark"] {
        #catppuccin(@darkFlavor);
        header[data-color-mode] {
          #catppuccin(@darkFlavor);
        }
      }
    }
  }
  [data-color-mode="light"][data-light-theme="dark"],
  [data-color-mode="dark"][data-dark-theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  [data-color-mode="light"][data-light-theme="light"],
  [data-color-mode="dark"][data-dark-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    .cm-placeholder {
      color: @subtext0;
    }

    accent-color: @accent;
    color: @text;

    --color-social-reaction-bg-reacted-hover: fade(@accent, 30%);
    --color-notifications-button-hover-bg: fade(@accent, 60%);
    --color-workflow-card-header-shadow: rgba(27, 31, 35, 0.04);
    --color-icon-directory: var(--fgColor-muted, var(--color-fg-muted));
    --color-calendar-halloween-graph-day-L1-bg: fade(
      @accent,
      40%
    ) !important;
    --color-calendar-halloween-graph-day-L2-bg: fade(
      @accent,
      60%
    ) !important;
    --color-calendar-halloween-graph-day-L3-bg: fade(
      @accent,
      80%
    ) !important;
    --color-calendar-halloween-graph-day-L4-bg: @accent !important;
    --color-calendar-winter-graph-day-L1-bg: fade(
      @accent,
      40%
    ) !important;
    --color-calendar-winter-graph-day-L2-bg: fade(
      @accent,
      60%
    ) !important;
    --color-calendar-winter-graph-day-L3-bg: fade(
      @accent,
      80%
    ) !important;
    --color-calendar-winter-graph-day-L4-bg: @accent !important;
    --color-calendar-graph-day-bg: @surface0 !important;
    --color-calendar-graph-day-border: transparent !important;
    --color-calendar-graph-day-L1-bg: fade(@accent, 40%) !important;
    --color-calendar-graph-day-L2-bg: fade(@accent, 60%) !important;
    --color-calendar-graph-day-L3-bg: fade(@accent, 80%) !important;
    --color-calendar-graph-day-L4-bg: @accent !important;
    --color-calendar-graph-day-L2-border: transparent !important;
    --color-calendar-graph-day-L3-border: transparent !important;
    --color-calendar-graph-day-L4-border: transparent !important;
    --contribution-default-bgColor-0: fade(@accent, 10%) !important;
    --contribution-default-bgColor-1: fade(@accent, 40%) !important;
    --contribution-default-bgColor-2: fade(@accent, 60%) !important;
    --contribution-default-bgColor-3: fade(@accent, 80%) !important;
    --contribution-default-bgColor-4: @accent !important;
    --color-user-mention-fg: @accent;
    --color-user-mention-bg: fade(@accent, 30%);
    --color-dashboard-feed-bg: var(--color-scale-gray-9);
    --color-mktg-btn-shadow-outline: rgba(255, 255, 255, 0.25) 0 0 0 1px inset;
    --color-marketing-icon-secondary: var(--color-scale-blue-5);
    --color-project-header-bg: var(--color-scale-gray-9);
    --color-project-sidebar-bg: var(--color-scale-gray-8);
    --color-project-gradient-in: var(--color-scale-gray-8);
    --color-project-gradient-out: rgba(22, 27, 34, 0);
    --color-diff-blob-selected-line-highlight-mix-blend-mode: screen;
    --topicTag-borderColor: #0000;
    --highlight-neutral-bgColor: fade(@yellow, 30%);
    --page-header-bgColor: @crust;
    --diffBlob-additionNum-bgColor: fade(@green, 30%);
    --diffBlob-additionNum-fgColor: @text;
    --diffBlob-additionLine-bgColor: fade(@green, 15%);
    --diffBlob-additionWord-bgColor: fade(@green, 30%);
    --diffBlob-additionWord-fgColor: @text;
    --diffBlob-deletionNum-bgColor: fade(@red, 30%);
    --diffBlob-deletionNum-fgColor: @text;
    --diffBlob-deletionLine-bgColor: fade(@red, 15%);
    --diffBlob-deletionWord-bgColor: fade(@red, 30%);
    --diffBlob-deletionWord-fgColor: @text;
    --diffBlob-hunkNum-bgColor-rest: fade(@accent, 40%);
    --diffBlob-hunkNum-bgColor-hover: fade(@accent, 75%);
    --diffBlob-hunkLine-bgColor: fade(@accent, 25%);
    --diffBlob-expander-iconColor: @subtext0;
    --diffBlob-emptyNum-bgColor: @mantle;
    --diffBlob-emptyLine-bgColor: @mantle;
    --codeMirror-fgColor: @text;
    --codeMirror-bgColor: @base;
    --codeMirror-gutters-bgColor: @base;
    --codeMirror-gutterMarker-fgColor-default: @base;
    --codeMirror-gutterMarker-fgColor-muted: @overlay0;
    --codeMirror-lineNumber-fgColor: @overlay1;
    --codeMirror-cursor-fgColor: @text;
